Fixpoint kwords_ok (ok : nat -> bool) (kn : list kentry) : bool :=
  match kn with
  | [] => true
  | KWord a w v :: r => evars_ok ok (a_base a) && evars_ok ok v && kwords_ok ok r
  | _ :: _ => false
  end.
