Hypothesis Hlive8 : ltac2:(zQ "b0!j7!it2!h4!lsa!mj7!mje!lu5!l6!tf!mif!na>1k$0>0@2$1@2$5N8^1@2$6^1Nc@3$2@1$a@1$7#k0@2$8?2E0@2$3Nh4@2$4^2N8@2$9?2f1^2").
Hypothesis A_lo : 0x400000000000 <= A + ZLO.
Hypothesis H_low : Hd + 144 <= A + ZLO.

Theorem throw_core : forall fx : FPState,
  exists (fx' : FPState) E' R' M' t,
       first_pad isPad G = Some t
    /\ msteps EhX_ubsan.SEGS (@mkst fx R0 (Z_to_bv 64 0x98110) M00 (seg_rom EhX_ubsan.SEGS))
                           (@mkst fx' R' (Z_to_bv 64 (pad_pc stof t)) M' (seg_rom EhX_ubsan.SEGS))
    /\ @fp_csr fx' = @fp_csr fx
    /\ regs_ok E' (PAD_regs (pad_sel t)) R' /\ know_ok EhX_ubsan.SEGS E' M' PAD_T
    /\ know_ok EhX_ubsan.SEGS E' M' (globals_kn 1)
    /\ ev E' 34%nat = Z_to_bv 64 (fr_sp (fst t))
    /\ (forall k, (k < 12)%nat -> ev E' (slot_var k) = live (fst t) k)
    /\ ev E' 0%nat = ev E0 0%nat /\ ev E' 2%nat = ev E0 2%nat /\ ev E' 3%nat = ev E0 3%nat /\ ev E' 4%nat = ev E0 4%nat
    /\ ev E' 27%nat = Z_to_bv 64 spN
    /\ (forall a : word, ~ (A + ZLO <= bv_unsigned a < A + 1856) -> ~ (Hd <= bv_unsigned a < Hd + 144) ->
                         ~ (0x10d1d0 <= bv_unsigned a < 0x10d1e0) -> ~ (0x10eb20 <= bv_unsigned a < 0x10eb27) -> M' a = M00 a)
